import { useEffect, useState, type ChangeEvent, type CSSProperties, type FormEvent, type ReactNode } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useWallet } from "../context/WalletContext";
import { useContractRead } from "../hooks/useContract";
import { decodeWriteResult, describeReadError, readContract, writeContract, hasContract, NETWORK, type WriteMethod, type ContractArg } from "../lib/contract";
import type { Appeal, Candidate, Checkpoint, CheckpointFinalization, CheckpointSet, Edge, Evidence, Funding, FundingPolicy, ImpactVerdict, LatentAssessment, LatentSet, LineageVerdict, Node, ObservationPolicy, Page } from "../lib/records";
import { bps, toEpoch } from "../lib/records";
import { CandidateCard, FundingTimeline, ImpactPanel, LatentSignals, LineageGraph, LoadState, PageHead, StatusPill, TxBanner } from "../components/UI";

export function Home(){return <><section className="hero"><div className="hero-copy"><p className="eyebrow">PUBLIC INFRASTRUCTURE, BEFORE CONSENSUS NOTICES</p><h1>Fund the public goods nobody knew were public goods <em>yet.</em></h1><p>SEEDLING watches obscure contributions mature, preserves their forgotten lineage, and unlocks recognition only as public value becomes real.</p><div className="hero-actions"><Link className="button primary" to="/discover">Explore candidates</Link><Link className="button ghost" to="/methodology">How it works</Link></div></div><div className="growth-map" aria-label="Protocol progression"><span className="soil">UNKNOWN<small>public artifact</small></span><i/><span>LATENT<small>GenLayer signal</small></span><i/><span>WATCHING<small>frozen checkpoints</small></span><i/><span className="canopy">SYSTEMIC<small>progressive recognition</small></span></div></section><section className="thesis-grid"><article><b>01</b><h2>Notice what is overlooked</h2><p>Permissionless discovery starts with compact public evidence, never private ranking.</p></article><article><b>02</b><h2>Separate potential from impact</h2><p>Latent significance asks what could matter. Checkpoints ask what demonstrably does.</p></article><article><b>03</b><h2>Remember who made it possible</h2><p>Acyclic lineage and evidence-based attribution keep foundational creators visible.</p></article></section><section className="flow-band"><p className="eyebrow">THE SEEDLING LOOP</p><div>{["Unknown project","Evidence accumulates","Latent signal","Impact emerges","Lineage resolves","Funding unlocks"].map((x,i)=><span key={x}><b>{i+1}</b>{x}</span>)}</div></section></>}

export function Discover(){const q=useContractRead<Page<Candidate>>("list_candidates",[0,50]);return <><PageHead eyebrow="LIVE CONTRACT DATA" title="Discover the overlooked" lede="Candidates are ordered by on-chain discovery. No popularity feed, paid placement, or hidden index." actions={<Link className="button primary" to="/register">Register candidate</Link>}/><LoadState loading={q.loading} error={q.error} empty={!q.data?.total}><div className="candidate-grid">{q.data?.items.map(c=><CandidateCard key={c.candidate_id} candidate={c}/>)}</div></LoadState></>}

type Detail={candidate:Candidate;latent?:LatentAssessment;latentSet?:LatentSet;checkpoints:Checkpoint[];evidence:Evidence[];nodes:Node[];edges:Edge[];funding:Funding[];appeals:Appeal[]};
export function CandidateDetail(){const {candidateId=""}=useParams();const [state,setState]=useState<{data?:Detail;loading:boolean;error?:string}>({loading:true});const [tick,setTick]=useState(0);const {wallet,submit}=useTx();const [stageError,setStageError]=useState<string>();
 useEffect(()=>{let live=true;(async()=>{try{const candidate=await readContract<Candidate>("get_candidate",[candidateId]);const [checkpoints,evidence,nodes,edges,funding,appeals]=await Promise.all([readContract<Page<Checkpoint>>("list_checkpoints",[candidateId,0,50]),readContract<Page<Evidence>>("list_candidate_evidence",[candidateId,0,50]),readContract<Page<Node>>("list_contribution_nodes",[candidateId,0,50]),readContract<Page<Edge>>("list_lineage_edges",[candidateId,0,50]),readContract<Page<Funding>>("list_candidate_funding_calculations",[candidateId,0,50]),readContract<Page<Appeal>>("list_candidate_appeals",[candidateId,0,50])]);let latent:LatentAssessment|undefined;if(candidate.latent_assessment_id)latent=await readContract<LatentAssessment>("get_latent_assessment",[candidate.latent_assessment_id]);let latentSet:LatentSet|undefined;try{latentSet=await readContract<LatentSet>("get_latent_evidence_set",[candidateId]);}catch{latentSet=undefined;}if(live)setState({loading:false,data:{candidate,latent,latentSet,checkpoints:checkpoints.items,evidence:evidence.items,nodes:nodes.items,edges:edges.items,funding:funding.items,appeals:appeals.items}});}catch(e){if(live)setState({loading:false,error:describeReadError("get_candidate",[candidateId],e)});}})();return()=>{live=false};},[candidateId,tick]);
 async function runStage(method:"freeze_latent_evidence"|"evaluate_latent_value"){setStageError(undefined);try{await submit(method,[candidateId]);setTick(t=>t+1);}catch(x){setStageError(x instanceof Error?x.message:"The protocol step could not be completed.");}}
 return <LoadState loading={state.loading} error={state.error}>{state.data&&<><PageHead eyebrow={`CANDIDATE #${candidateId}`} title={state.data.candidate.name} lede={state.data.candidate.description} actions={<StatusPill value={state.data.candidate.status}/>}/><div className="meta-strip"><a href={state.data.candidate.primary_artifact_url} target="_blank" rel="noreferrer">Public artifact ↗</a><span>{state.data.candidate.candidate_type.replaceAll("_"," ")}</span><span>Origin {state.data.candidate.origin_date}</span><span>Policies O{state.data.candidate.observation_policy_id} / F{state.data.candidate.funding_policy_id}</span></div><div className="dual-metric">{state.data.latent?<LatentSignals assessment={state.data.latent}/>:<section className="signal-panel"><h2>Latent significance</h2><p>Awaiting frozen evidence and GenLayer adjudication.</p></section>}<ImpactPanel status={state.data.candidate.status} latest={state.data.checkpoints.at(-1) as unknown as Record<string,unknown>}/></div><Section title="Evidence ledger" action={<Link to={`/candidates/${candidateId}/evidence`}>Submit evidence →</Link>}><div className="evidence-list">{state.data.evidence.length?state.data.evidence.map(e=><article key={e.evidence_id}><StatusPill value={e.status}/><strong>{e.source_type.replaceAll("_"," ")}</strong><p>{e.summary}</p><a href={e.source_url} target="_blank" rel="noreferrer">{e.source_host} ↗</a></article>):<p className="muted">No latent evidence records yet.</p>}</div>{state.data.latentSet&&<LatentStage set={state.data.latentSet} locked={!wallet.account||wallet.wrongNetwork} error={stageError} onRun={m=>void runStage(m)}/>}</Section><Section title="Impact checkpoints" action={<Link to={`/candidates/${candidateId}/checkpoints`}>Manage checkpoints →</Link>}><div className="checkpoint-row">{state.data.checkpoints.length?state.data.checkpoints.map(cp=><Link to={`/candidates/${candidateId}/checkpoints/${cp.checkpoint_id}`} key={cp.checkpoint_id}><small>#{cp.checkpoint_id}</small><StatusPill value={cp.status}/><b>{cp.evidence_count} evidence</b></Link>):<p className="muted">No impact observation periods yet.</p>}</div></Section><Section title="Foundational lineage" action={<Link to={`/candidates/${candidateId}/lineage`}>Open explorer →</Link>}><LineageGraph nodes={state.data.nodes} edges={state.data.edges}/></Section><div className="two-col"><Section title="Dormant funding"><FundingTimeline items={state.data.funding}/><Link to={`/candidates/${candidateId}/funding`}>Full funding history →</Link></Section><Section title="Appeals & finality"><p>{state.data.appeals.length} appeal record(s)</p><Link to={`/candidates/${candidateId}/appeals`}>Inspect appeals →</Link></Section></div></>}</LoadState>}

function Section({title,action,children}:{title:string;action?:ReactNode;children:ReactNode}){return <section className="content-section"><div className="section-title"><h2>{title}</h2>{action}</div>{children}</section>}

function useTx(){const wallet=useWallet();async function submit(method:WriteMethod,args:ContractArg[]){if(!wallet.account||!wallet.provider)throw new Error("Connect a wallet first.");if(wallet.wrongNetwork)throw new Error(`Switch to ${NETWORK.name} first.`);return writeContract(wallet.account,wallet.provider,method,args,wallet.setTx);}return {wallet,submit}}

export function Register(){const {wallet,submit}=useTx();const navigate=useNavigate();const [error,setError]=useState<string>();const obs=useContractRead<Page<ObservationPolicy>>("list_observation_policies",[0,50]);const fund=useContractRead<Page<FundingPolicy>>("list_funding_policies",[0,50]);const activeObs=(obs.data?.items??[]).filter(p=>p.status==="ACTIVE");const activeFund=(fund.data?.items??[]).filter(p=>p.status==="ACTIVE");const policiesReady=activeObs.length>0&&activeFund.length>0;const policiesLoading=obs.loading||fund.loading;async function onSubmit(e:FormEvent<HTMLFormElement>){e.preventDefault();setError(undefined);const f=new FormData(e.currentTarget);const args:ContractArg[]=["name","description","candidate_type","primary_artifact_url","origin_date"].map(k=>String(f.get(k)));args.push(true,String(f.get("observation_policy_id")),String(f.get("funding_policy_id")));try{await submit("register_candidate",args);navigate("/discover");}catch(x){setError(x instanceof Error?x.message:"Registration failed.");}}
 return <><PageHead eyebrow="PERMISSIONLESS DISCOVERY" title="Register an overlooked contribution" lede="Bind the candidate to immutable observation and funding policy versions. Registration is a claim, not an endorsement."/><TxBanner/><form className="protocol-form" onSubmit={e=>void onSubmit(e)}><Field name="name" label="Project name" required maxLength={120}/><Field name="description" label="Why might this matter?" textarea required maxLength={2000}/><label>Candidate type<select name="candidate_type"><option>OPEN_SOURCE_LIBRARY</option><option>DATASET</option><option>RESEARCH</option><option>DOCUMENTATION</option><option>DEVELOPER_TOOL</option><option>PUBLIC_ARCHIVE</option><option>COMMUNITY_INFRASTRUCTURE</option><option>PROTOCOL_COMPONENT</option><option>EDUCATIONAL_RESOURCE</option><option>CUSTOM</option></select></label><Field name="primary_artifact_url" label="Public artifact URL" type="url" required/><Field name="origin_date" label="Origin date" placeholder="YYYY-MM-DD" required/>{policiesLoading?<p className="hint">Reading bound policy versions from the contract…</p>:policiesReady?<div className="form-row"><label>Observation policy<select name="observation_policy_id">{activeObs.map(p=><option key={p.policy_id} value={p.policy_id}>#{p.policy_id} — {p.name} (v{p.version})</option>)}</select></label><label>Funding policy<select name="funding_policy_id">{activeFund.map(p=><option key={p.funding_policy_id} value={p.funding_policy_id}>#{p.funding_policy_id} — {p.name} (v{p.version})</option>)}</select></label></div>:<div className="callout" role="status"><strong>No active policies exist yet.</strong><p>A candidate must bind an active observation policy and an active funding policy. Neither can be invented at registration time—create them first, then return here.</p><Link className="button" to="/policies">Create the first policies</Link></div>}{error&&<p className="form-error" role="alert">{error}</p>}<button className="button primary" disabled={!wallet.account||wallet.wrongNetwork||!policiesReady}>Submit registration</button>{!wallet.account&&<p className="hint">Connect a StudioNet wallet to submit.</p>}</form></>}

function Field(props:{name:string;label:string;textarea?:boolean;type?:string;required?:boolean;maxLength?:number;placeholder?:string;min?:number;max?:number;defaultValue?:string|number;value?:string;onChange?:(e:ChangeEvent<HTMLInputElement>)=>void}){const {label,textarea,onChange,...rest}=props;return <label>{label}{textarea?<textarea {...rest}/>:<input {...rest} onChange={onChange}/>}</label>}

// The digest bound to an evidence row is taken from the text the validators
// render, which nothing off-chain reproduces -- a submitter cannot compute it,
// and a wrong value only surfaces as a rollback after the evidence set is
// frozen. So the form asks the contract instead of asking the submitter to
// guess. One transaction, no state written, and the answer drops straight into
// the digest field. Shared by the candidate and checkpoint evidence forms
// because both bind the identical rule.
function ArchivedSourceFields({submit,locked,onValues,urlName="url",hashName="hash",urlLabel="Archived snapshot URL",hashLabel="Rendered content digest"}:{submit:(m:WriteMethod,a:ContractArg[])=>Promise<unknown>;locked:boolean;onValues:(v:{url:string;digest:string})=>void;urlName?:string;hashName?:string;urlLabel?:string;hashLabel?:string}){
 const [url,setUrl]=useState("");const [digest,setDigest]=useState("");
 useEffect(()=>{onValues({url,digest});},[url,digest]);// eslint-disable-line react-hooks/exhaustive-deps
 const [busy,setBusy]=useState(false);const [note,setNote]=useState<string>();const [error,setError]=useState<string>();
 async function preview(){
  setError(undefined);setNote(undefined);setBusy(true);
  try{
   const receipt=await submit("preview_evidence_digest",[url]);
   const decoded=decodeWriteResult(receipt);
   const report=(typeof decoded==="string"?JSON.parse(decoded):decoded) as {digest?:string;rendered_chars?:number}|undefined;
   if(!report?.digest)throw new Error("The contract accepted the preview but its answer could not be read. Check the transaction in the explorer.");
   setDigest(report.digest);
   setNote(`Digest computed from ${report.rendered_chars ?? "?"} rendered characters. It is filled in below.`);
  }catch(x){setError(x instanceof Error?x.message:"Could not preview the digest.");}
  finally{setBusy(false);}
 }
 return <><Field name={urlName} label={urlLabel} type="url" required placeholder="https://web.archive.org/web/20240101000000id_/https://example.org/page" value={url} onChange={e=>setUrl(e.target.value)}/>
  <p className="hint">Not archived yet? Save the page at <a href="https://web.archive.org/save" target="_blank" rel="noreferrer">web.archive.org/save</a> first, then paste the snapshot address it produces. An ordinary link to the live page is rejected: only an archived snapshot can still be shown to have said what it said when the evidence was judged.</p>
  <div className="latent-actions"><button type="button" className="button" disabled={locked||busy||!url} onClick={()=>void preview()}>{busy?"Asking the contract...":"Preview digest"}</button></div>
  {locked&&<p className="hint">Connect a StudioNet wallet to preview the digest. Previewing asks the validators to render the page, so it is a transaction like any other.</p>}
  {!locked&&!url&&<p className="hint">Paste the archived snapshot URL above to enable the digest preview.</p>}
  <Field name={hashName} label={hashLabel} required placeholder="sha256:..." value={digest} onChange={e=>setDigest(e.target.value)}/>
  {note&&<p className="hint">{note}</p>}
  {error&&<p className="form-error" role="alert">{error}</p>}
  <p className="hint">Sources must be raw Wayback snapshots (the <code>id_</code> modifier) so the bytes behind the URL can never change. The digest must match the text the validators render, which nothing off-chain reproduces -- use Preview digest rather than computing one yourself. A mismatch stops adjudication instead of judging unattested content.</p></>}

export function EvidencePage(){const {candidateId=""}=useParams();const q=useContractRead<Page<Evidence>>("list_candidate_evidence",[candidateId,0,50]);const {wallet,submit}=useTx();const locked=!wallet.account||wallet.wrongNetwork;const [error,setError]=useState<string>();const [src,setSrc]=useState({url:"",digest:""});const [srcKey,setSrcKey]=useState(0);async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);try{await submit("submit_candidate_evidence",[candidateId,String(f.get("type")),src.url,src.digest,String(f.get("summary")),toEpoch(String(f.get("start"))),toEpoch(String(f.get("end")))]);form.reset();setSrc({url:"",digest:""});setSrcKey(k=>k+1);await q.refresh();}catch(x){setError(x instanceof Error?x.message:"Submission failed.");}}return <><PageHead eyebrow="PUBLIC EVIDENCE" title="Candidate evidence" lede="Only compact URL, digest, period, and bounded metadata are stored. Page content remains off-chain and untrusted."/><div className="two-col"><form className="protocol-form compact" onSubmit={e=>void send(e)}><label>Evidence category<select name="type"><option>SOURCE_REPOSITORY</option><option>PACKAGE_REGISTRY</option><option>DEPENDENCY_GRAPH</option><option>DOWNSTREAM_REPOSITORY</option><option>PUBLIC_USAGE_RECORD</option><option>RESEARCH_CITATION</option></select></label><ArchivedSourceFields key={srcKey} submit={submit} locked={locked} onValues={setSrc}/><Field name="summary" label="Bounded summary" textarea required maxLength={1000}/><div className="form-row"><Field name="start" label="Period start" type="date" required/><Field name="end" label="Period end" type="date" required/></div>{error&&<p role="alert" className="form-error">{error}</p>}<button className="button primary">Submit evidence</button></form><LoadState loading={q.loading} error={q.error} empty={!q.data?.total} emptyTitle="No evidence submitted yet" emptyBody="Evidence is a public URL, a content digest, and a bounded period. Nothing here is inferred or back-filled." emptyAction={null}><div className="evidence-list">{q.data?.items.map(e=><article key={e.evidence_id}><StatusPill value={e.status}/><strong>{e.source_type}</strong><p>{e.summary}</p></article>)}</div></LoadState></div></>}

export function CheckpointsPage(){const {candidateId=""}=useParams();const q=useContractRead<Page<Checkpoint>>("list_checkpoints",[candidateId,0,50]);const cand=useContractRead<Candidate>("get_candidate",[candidateId]);const {wallet,submit}=useTx();const navigate=useNavigate();const [error,setError]=useState<string>();const eligible=cand.data?["WATCHING","EMERGING","MATERIAL","SYSTEMIC"].includes(cand.data.status):false;const hasOpen=(q.data?.items??[]).some(cp=>!["FINALIZED","VOIDED"].includes(cp.status));async function open(e:FormEvent<HTMLFormElement>){e.preventDefault();setError(undefined);const f=new FormData(e.currentTarget);try{await submit("open_checkpoint",[candidateId,toEpoch(String(f.get("start"))),toEpoch(String(f.get("end")))]);const fresh=await readContract<Page<Checkpoint>>("list_checkpoints",[candidateId,0,50]);await q.refresh();const newest=fresh.items.reduce((a,b)=>Number(b.checkpoint_id)>Number(a.checkpoint_id)?b:a,fresh.items[0]);if(newest)navigate(`/candidates/${candidateId}/checkpoints/${newest.checkpoint_id}`);}catch(x){setError(x instanceof Error?x.message:"Could not open the checkpoint.");}}return <><PageHead eyebrow="LONGITUDINAL OBSERVATION" title="Impact checkpoints" lede="Each bounded period freezes its own evidence before GenLayer judges realized public value." actions={cand.data&&<StatusPill value={cand.data.status}/>}/><TxBanner/>{eligible?<form className="protocol-form compact" onSubmit={e=>void open(e)}><div className="section-title"><h2>Open an observation period</h2></div><p className="muted">A checkpoint freezes its own evidence for a bounded past period, then asks GenLayer to judge realized public value. Only the candidate submitter may open one, and only one may be active at a time.</p><div className="form-row"><Field name="start" label="Period start" type="date" required/><Field name="end" label="Period end" type="date" required/></div>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button primary" disabled={!wallet.account||wallet.wrongNetwork||hasOpen}>Open checkpoint</button>{hasOpen&&<p className="hint">This candidate already has an active checkpoint. Finalize or void it before opening another.</p>}{!wallet.account&&<p className="hint">Connect a StudioNet wallet to open a checkpoint.</p>}</form>:<p className="hint">Checkpoints open only after latent adjudication moves the candidate to WATCHING or beyond. This candidate is {cand.data?.status||"loading"}.</p>}<LoadState loading={q.loading} error={q.error} empty={!q.data?.total} emptyTitle="No observation periods yet" emptyBody="Each checkpoint freezes its own evidence before GenLayer judges realized public value." emptyAction={null}><div className="checkpoint-table">{q.data?.items.map(cp=><Link key={cp.checkpoint_id} to={`/candidates/${candidateId}/checkpoints/${cp.checkpoint_id}`}><b>Checkpoint {cp.checkpoint_id}</b><span>{new Date(cp.period_start*1000).toLocaleDateString()} — {new Date(cp.period_end*1000).toLocaleDateString()}</span><StatusPill value={cp.status}/></Link>)}</div></LoadState></>}
export function CheckpointDetail(){const {candidateId="",checkpointId=""}=useParams();const cp=useContractRead<Checkpoint>("get_checkpoint",[checkpointId]);const evidence=useContractRead<Page<Evidence>>("list_checkpoint_evidence",[checkpointId,0,50]);const set=useContractRead<CheckpointSet>("get_checkpoint_evidence_set",[checkpointId]);const {wallet,submit}=useTx();const [error,setError]=useState<string>();const locked=!wallet.account||wallet.wrongNetwork;const verdict=useContractRead<ImpactVerdict>("get_impact_verdict",[cp.data?.impact_verdict_id||""]);const lineage=useContractRead<LineageVerdict>("get_lineage_verdict",[cp.data?.lineage_verdict_id||""]);const funding=useContractRead<Page<Funding>>("list_candidate_funding_calculations",[candidateId,0,50]);const appeals=useContractRead<Page<Appeal>>("list_candidate_appeals",[candidateId,0,50]);const fin=useContractRead<CheckpointFinalization>("get_checkpoint_finalization",[checkpointId]);const [src,setSrc]=useState({url:"",digest:""});const [srcKey,setSrcKey]=useState(0);const refreshAll=async()=>{await Promise.all([cp.refresh(),evidence.refresh(),set.refresh(),lineage.refresh(),funding.refresh(),appeals.refresh(),fin.refresh()]);};async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();setError(undefined);const form=e.currentTarget;const f=new FormData(form);try{await submit("submit_checkpoint_evidence",[checkpointId,String(f.get("type")),src.url,src.digest,String(f.get("summary")),toEpoch(String(f.get("start"))),toEpoch(String(f.get("end")))]);form.reset();setSrc({url:"",digest:""});setSrcKey(k=>k+1);await refreshAll();}catch(x){setError(x instanceof Error?x.message:"Submission failed.");}}async function stage(method:"freeze_checkpoint"|"evaluate_public_value"|"evaluate_lineage"|"calculate_funding"){setError(undefined);try{await submit(method,[checkpointId]);await refreshAll();}catch(x){setError(x instanceof Error?x.message:"The protocol step could not be completed.");}}async function finalize(){setError(undefined);try{await submit("finalize_checkpoint",[candidateId,checkpointId]);await refreshAll();}catch(x){setError(x instanceof Error?x.message:"The checkpoint could not be finalized.");}}const funded=(funding.data?.items??[]).some(f=>f.checkpoint_id===checkpointId);const checkpointAppeals=(appeals.data?.items??[]).filter(a=>a.checkpoint_id===checkpointId);const unresolvedAppeal=checkpointAppeals.some(a=>a.status!=="RESOLVED");const finalized=fin.data?.finalized??false;const status=cp.data?.status;const collecting=status==="OPEN";const frozen=status==="EVIDENCE_FROZEN";return <><PageHead eyebrow={`CANDIDATE #${candidateId}`} title={`Checkpoint ${checkpointId}`} lede="Submission, consensus adjudication, lineage, funding, appeal, and finalization remain distinct states." actions={cp.data&&<StatusPill value={cp.data.status}/>}/><TxBanner/><LoadState loading={cp.loading||evidence.loading} error={cp.error||evidence.error}><div className="two-col"><Section title="Observation window"><p>{cp.data&&`${new Date(cp.data.period_start*1000).toLocaleString()} — ${new Date(cp.data.period_end*1000).toLocaleString()}`}</p><p>{cp.data?.evidence_count} compact evidence references</p></Section><Section title="Lifecycle IDs"><dl><dt>Impact verdict</dt><dd>{cp.data?.impact_verdict_id||"pending"}</dd><dt>Lineage verdict</dt><dd>{cp.data?.lineage_verdict_id||"pending"}</dd><dt>Appeal</dt><dd>{cp.data?.appeal_id||"none"}</dd></dl></Section></div>{collecting&&<Section title="Submit checkpoint evidence"><form className="protocol-form compact" onSubmit={e=>void send(e)}><label>Evidence category<select name="type"><option>PRODUCTION_REFERENCE</option><option>DEPENDENCY_GRAPH</option><option>DOWNSTREAM_REPOSITORY</option><option>PUBLIC_USAGE_RECORD</option><option>PACKAGE_REGISTRY</option><option>RESEARCH_CITATION</option><option>SOURCE_REPOSITORY</option><option>ECOSYSTEM_DOCUMENTATION</option></select></label><ArchivedSourceFields key={srcKey} submit={submit} locked={locked} onValues={setSrc}/><Field name="summary" label="Bounded summary" textarea required maxLength={1000}/><div className="form-row"><Field name="start" label="Period start" type="date" required/><Field name="end" label="Period end" type="date" required/></div>{error&&<p role="alert" className="form-error">{error}</p>}<button className="button primary" disabled={locked}>Submit checkpoint evidence</button></form></Section>}{set.data&&(collecting||frozen)&&<div className="latent-actions"><div className="gate"><span>evidence <b>{set.data.evidence_count}</b></span><span className={set.data.distinct_category_count>=set.data.minimum_evidence_categories?"met":undefined}>categories <b>{set.data.distinct_category_count}/{set.data.minimum_evidence_categories}</b></span><span className={set.data.distinct_host_count>=set.data.minimum_independent_sources?"met":undefined}>independent hosts <b>{set.data.distinct_host_count}/{set.data.minimum_independent_sources}</b></span><span>{frozen?"evidence frozen":"open"}</span></div>{collecting&&<button className="button primary" disabled={locked||!set.data.requirements_met} onClick={()=>void stage("freeze_checkpoint")}>Freeze checkpoint evidence</button>}{frozen&&<button className="button primary" disabled={locked} onClick={()=>void stage("evaluate_public_value")}>Evaluate public value</button>}</div>}{collecting&&set.data&&!set.data.requirements_met&&<p className="hint">The bound observation policy requires {set.data.minimum_evidence_categories} distinct evidence categories across {set.data.minimum_independent_sources} independent hosts before this period can be frozen.</p>}{collecting&&set.data?.requirements_met&&<p className="hint">Freezing is irreversible and happens once. No further checkpoint evidence can be submitted afterwards.</p>}{error&&!collecting&&<p className="form-error" role="alert">{error}</p>}{verdict.data&&<div className="dual-metric"><section className="signal-panel"><p className="eyebrow">REALIZED PUBLIC VALUE</p><div className="orb" style={{"--score":`${bps(verdict.data.public_value_bps)}%`} as CSSProperties}><strong>{Math.round(bps(verdict.data.public_value_bps))}</strong><span>value</span></div><div className="signals"><Signal label="Dependency importance" value={verdict.data.dependency_importance_bps}/><Signal label="Independent adoption" value={verdict.data.independent_adoption_bps}/><Signal label="Replacement difficulty" value={verdict.data.replacement_difficulty_bps}/><Signal label="Persistence" value={verdict.data.persistence_bps}/><Signal label="Gaming risk" value={verdict.data.gaming_risk_bps}/></div><p className="muted">{verdict.data.summary}</p></section><ImpactPanel status={verdict.data.importance_tier} latest={verdict.data as unknown as Record<string,unknown>}/></div>}{verdict.data&&<div className="latent-actions">{!cp.data?.lineage_verdict_id&&<button className="button primary" disabled={locked} onClick={()=>void stage("evaluate_lineage")}>Evaluate lineage</button>}{cp.data?.lineage_verdict_id&&!funded&&<button className="button primary" disabled={locked} onClick={()=>void stage("calculate_funding")}>Calculate funding</button>}{funded&&!finalized&&<p className="hint">Funding calculated for this checkpoint.</p>}</div>}{(funded||finalized)&&<Section title="Finalization">{finalized?<><p className="muted">This checkpoint is irreversibly <b>{fin.data?.status}</b>{fin.data?.finalized_at?` as of ${new Date((fin.data.finalized_at)*1000).toLocaleString()}`:""}. The effective result below is the one funding was recognized against, and the candidate is free to open its next observation period.</p><dl><dt>Effective appeal</dt><dd>{fin.data?.effective_appeal_id||"none"}</dd><dt>Effective impact verdict</dt><dd>{fin.data?.effective_impact_verdict_id||"none"}</dd><dt>Effective lineage verdict</dt><dd>{fin.data?.effective_lineage_verdict_id||"none"}</dd><dt>Effective funding calculation</dt><dd>{fin.data?.effective_funding_calculation_id||"none"}</dd></dl><Link className="button primary" to={`/candidates/${candidateId}/checkpoints`}>Open the next checkpoint</Link></>:<><p className="muted">Finalizing locks the effective result, releases the candidate's active checkpoint slot, and lets the next observation period begin. Only the candidate submitter may finalize, and it cannot be undone.</p><div className="latent-actions"><button className="button primary" disabled={locked||unresolvedAppeal||status!=="EVALUATED"} onClick={()=>void finalize()}>Finalize checkpoint</button></div>{unresolvedAppeal&&<p className="hint">An open appeal on this checkpoint blocks finalization. Adjudicate it on the appeals page first.</p>}{!unresolvedAppeal&&<p className="hint">Appeals stay possible until this checkpoint is finalized. Finalize once the effective result should become permanent.</p>}</>}</Section>}
{lineage.data&&<Section title="Lineage attribution"><p className="muted">{lineage.data.summary}</p><p>Attribution confidence: <b>{Math.round(bps(lineage.data.attribution_confidence_bps))}</b></p><dl>{lineage.data.contributor_allocations.map(a=><span key={a.node_id}><dt>Node #{a.node_id}</dt><dd>{Math.round(bps(a.attribution_bps))}%</dd></span>)}</dl></Section>}
<Section title="Checkpoint evidence"><div className="evidence-list">{evidence.data?.items.length?evidence.data.items.map(e=><article key={e.evidence_id}><StatusPill value={e.status}/><strong>{e.source_type.replaceAll("_"," ")}</strong><p>{e.summary}</p><a href={e.source_url} target="_blank" rel="noreferrer">{e.source_host} ↗</a></article>):<p className="muted">No checkpoint evidence yet.</p>}</div></Section></LoadState></>}
function Signal({label,value}:{label:string;value:number}){return <div className="signal"><strong>{label}</strong><div className="track"><span style={{width:`${bps(value)}%`}}/></div><b>{Math.round(bps(value))}</b></div>}

const ARTIFACT_TYPES=["SOURCE_CODE","DATASET","RESEARCH","DOCUMENTATION","SPECIFICATION","ARCHIVE","TOOLING","INFRASTRUCTURE","EDUCATIONAL_RESOURCE","OTHER"];
const CONTRIBUTION_ROLES=["ORIGINAL_AUTHOR","FORK_MAINTAINER","MAJOR_REWRITER","EXTENSION_AUTHOR","MAINTAINER","DOCUMENTATION_AUTHOR","DATA_CURATOR","RESEARCHER","MIGRATION_AUTHOR","OTHER"];
const LINEAGE_RELATIONSHIPS=["FORKED_FROM","DERIVED_FROM","REWRITES","EXTENDS","INCORPORATES","DOCUMENTS","MAINTAINS","MIGRATES","REPLACES","INSPIRES"];
export function LineagePage(){const {candidateId=""}=useParams();const nodes=useContractRead<Page<Node & {node_id:string}>>("list_contribution_nodes",[candidateId,0,50]);const edges=useContractRead<Page<Edge>>("list_lineage_edges",[candidateId,0,50]);const {wallet,submit}=useTx();const [nodeError,setNodeError]=useState<string>();const [edgeError,setEdgeError]=useState<string>();const [src,setSrc]=useState({url:"",digest:""});const [srcKey,setSrcKey]=useState(0);const locked=!wallet.account||wallet.wrongNetwork;const refreshAll=async()=>{await Promise.all([nodes.refresh(),edges.refresh()]);};async function addNode(e:FormEvent<HTMLFormElement>){e.preventDefault();setNodeError(undefined);const form=e.currentTarget;const f=new FormData(form);try{await submit("register_contribution_node",[candidateId,String(f.get("contributor")),String(f.get("artifact_type")),src.url,src.digest,String(f.get("role")),String(f.get("summary"))]);form.reset();setSrc({url:"",digest:""});setSrcKey(k=>k+1);await refreshAll();}catch(x){setNodeError(x instanceof Error?x.message:"Could not register the contribution node.");}}async function addEdge(e:FormEvent<HTMLFormElement>){e.preventDefault();setEdgeError(undefined);const form=e.currentTarget;const f=new FormData(form);const from=String(f.get("from_node_id"));const to=String(f.get("to_node_id"));if(from===to){setEdgeError("A node cannot descend from itself.");return;}try{await submit("register_lineage_edge",[candidateId,from,to,String(f.get("relationship_type")),[],Number(f.get("claimed_strength_bps"))]);form.reset();await refreshAll();}catch(x){setEdgeError(x instanceof Error?x.message:"Could not register the lineage edge.");}}const nodeItems=nodes.data?.items??[];return <><PageHead eyebrow="HISTORICAL ATTRIBUTION" title="Lineage explorer" lede="Claims form an acyclic provenance graph. GenLayer—not role labels or edge strength—adjudicates causal attribution."/><TxBanner/><div className="two-col"><Section title="Register a contribution node"><form className="protocol-form compact" onSubmit={e=>void addNode(e)}><Field name="contributor" label="Contributor address" required placeholder="0x…"/><label>Artifact type<select name="artifact_type">{ARTIFACT_TYPES.map(t=><option key={t} value={t}>{t.replaceAll("_"," ")}</option>)}</select></label><ArchivedSourceFields key={srcKey} submit={submit} locked={locked} onValues={setSrc} urlName="artifact_url" hashName="artifact_hash" urlLabel="Archived artifact snapshot URL" hashLabel="Rendered artifact digest"/><label>Role<select name="role">{CONTRIBUTION_ROLES.map(r=><option key={r} value={r}>{r.replaceAll("_"," ")}</option>)}</select></label><Field name="summary" label="Bounded summary" textarea required maxLength={1000}/>{nodeError&&<p className="form-error" role="alert">{nodeError}</p>}<button className="button primary" disabled={locked}>Register contribution node</button></form></Section><Section title="Claim a lineage edge"><form className="protocol-form compact" onSubmit={e=>void addEdge(e)}>{nodeItems.length<2?<p className="hint">Register at least two contribution nodes before claiming a relationship between them.</p>:<><div className="form-row"><label>From node<select name="from_node_id">{nodeItems.map(n=><option key={n.node_id} value={n.node_id}>#{n.node_id} — {n.role.replaceAll("_"," ")}</option>)}</select></label><label>To node<select name="to_node_id">{nodeItems.map(n=><option key={n.node_id} value={n.node_id}>#{n.node_id} — {n.role.replaceAll("_"," ")}</option>)}</select></label></div><label>Relationship<select name="relationship_type">{LINEAGE_RELATIONSHIPS.map(r=><option key={r} value={r}>{r.replaceAll("_"," ")}</option>)}</select></label><Field name="claimed_strength_bps" label="Claimed strength (0-10000 bps)" type="number" min={0} max={10000} defaultValue={7000} required/>{edgeError&&<p className="form-error" role="alert">{edgeError}</p>}<button className="button primary" disabled={locked}>Claim lineage edge</button></>}</form></Section></div><LoadState loading={nodes.loading||edges.loading} error={nodes.error||edges.error} empty={!nodes.data?.total} emptyTitle="No lineage claims yet" emptyBody="Contribution nodes and edges are append-only claims, not attribution proof." emptyAction={null}><LineageGraph nodes={nodes.data?.items??[]} edges={edges.data?.items??[]}/><aside className="callout">A downstream project may become famous while its foundational ancestor remains attributable. Every edge is evidence-supported, but still only a claim until adjudication.</aside></LoadState></>}
export function FundingPage(){const {candidateId=""}=useParams();const q=useContractRead<Page<Funding>>("list_candidate_funding_calculations",[candidateId,0,50]);return <><PageHead eyebrow="PROTOCOL ACCOUNTING" title="Dormant funding progression" lede="Each checkpoint unlocks only the incremental policy-permitted amount. These are accounting units—not transferred tokens."/><LoadState loading={q.loading} error={q.error} empty={!q.data?.total} emptyTitle="No funding calculated yet" emptyBody="Recognition unlocks only after a checkpoint is adjudicated under its bound funding policy." emptyAction={null}><FundingTimeline items={q.data?.items??[]}/></LoadState></>}
const APPEAL_GROUNDS=["IMPACT_OVERSTATED","IMPACT_UNDERSTATED","LINEAGE_MISATTRIBUTED","ORIGINAL_CONTRIBUTION_IGNORED","DERIVATIVE_WORK_OVERWEIGHTED","INDEPENDENCE_MISCLASSIFIED","GAMING_RISK_MISCLASSIFIED","SUBSTITUTE_ANALYSIS_WRONG","EVIDENCE_OMITTED","INVALID_EVIDENCE_USED","FUNDING_POLICY_MISAPPLIED"];
export function AppealsPage(){const {candidateId=""}=useParams();const q=useContractRead<Page<Appeal>>("list_candidate_appeals",[candidateId,0,50]);const checkpoints=useContractRead<Page<Checkpoint>>("list_checkpoints",[candidateId,0,50]);const {wallet,submit}=useTx();const [error,setError]=useState<string>();const locked=!wallet.account||wallet.wrongNetwork;const appealable=(checkpoints.data?.items??[]).filter(cp=>cp.status==="EVALUATED");const refreshAll=async()=>{await Promise.all([q.refresh(),checkpoints.refresh()]);};async function open(e:FormEvent<HTMLFormElement>){e.preventDefault();setError(undefined);const form=e.currentTarget;const f=new FormData(form);try{await submit("open_appeal",[candidateId,String(f.get("checkpoint_id")),String(f.get("ground")),[],String(f.get("statement"))]);form.reset();await refreshAll();}catch(x){setError(x instanceof Error?x.message:"Could not open the appeal.");}}async function evaluate(appealId:string){setError(undefined);try{await submit("evaluate_appeal",[appealId]);await refreshAll();}catch(x){setError(x instanceof Error?x.message:"The appeal could not be adjudicated.");}}return <><PageHead eyebrow="CONTESTABLE, THEN FINAL" title="Appeals" lede="Original verdicts remain immutable. UPHOLD, MODIFY, or VOID creates an explicit effective result before irreversible finalization."/><TxBanner/><Section title="Open an appeal">{appealable.length?<form className="protocol-form compact" onSubmit={e=>void open(e)}><label>Checkpoint<select name="checkpoint_id">{appealable.map(cp=><option key={cp.checkpoint_id} value={cp.checkpoint_id}>Checkpoint #{cp.checkpoint_id}</option>)}</select></label><label>Ground<select name="ground">{APPEAL_GROUNDS.map(g=><option key={g} value={g}>{g.replaceAll("_"," ")}</option>)}</select></label><Field name="statement" label="Statement" textarea required maxLength={1000}/>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button primary" disabled={locked}>Open appeal</button></form>:<p className="hint">No checkpoint on this candidate is currently in an appealable state (EVALUATED, with funding calculated).</p>}</Section><LoadState loading={q.loading} error={q.error} empty={!q.data?.total} emptyTitle="No appeals filed" emptyBody="Verdicts stay contestable until a checkpoint is irreversibly finalized." emptyAction={null}><div className="appeal-list">{q.data?.items.map(a=><article key={a.appeal_id}><div><b>Appeal {a.appeal_id}</b><StatusPill value={a.status}/></div><h2>{a.ground.replaceAll("_"," ")}</h2><p>{a.statement}</p><strong>{a.decision||"Awaiting adjudication"}</strong>{a.status==="OPEN"&&<button className="button" disabled={locked} onClick={()=>void evaluate(a.appeal_id)}>Evaluate appeal</button>}</article>)}</div></LoadState></>}

export function Methodology(){return <><PageHead eyebrow="PROTOCOL METHODOLOGY" title="Potential is not proof. Popularity is not public value." lede="SEEDLING combines substantive GenLayer judgment with deterministic storage, lifecycle, and funding invariants."/><div className="method-grid"><Section title="Latent significance"><p>Forward-looking assessment of early reuse, uniqueness, substitutes, maintainer health, experimentation, accessibility, and ecosystem position.</p></Section><Section title="Current impact"><p>Checkpoint-specific realized adoption, persistence, dependency importance, replacement difficulty, and manipulation risk.</p></Section><Section title="Comparative consensus"><p>Frozen evidence → bounded public rendering → explicit criteria → independent comparative validators → exact schema → write-once record.</p></Section><Section title="Progressive recognition"><p>Deterministic policy caps and cumulative accounting prevent raw model output, replay, or fame from producing a maximum unlock.</p></Section></div></>}
export function ContractStatus(){const q=useContractRead<Record<string,unknown>>("get_protocol_info",[]);return <><PageHead eyebrow="DIRECT CONTRACT INTEGRATION" title="Protocol status" lede="The browser talks directly to the configured Intelligent Contract. No proxy, indexer, or canonical off-chain cache."/><div className="status-board"><div><small>NETWORK</small><strong>{NETWORK.name}</strong><span>chain {NETWORK.id}</span></div><div><small>CONTRACT</small><strong>{hasContract?"Configured":"Required"}</strong><span>{hasContract?"LIVE CONTRACT DATA":"Set VITE_SEEDLING_CONTRACT_ADDRESS"}</span></div><div><small>ABI</small><strong>57 methods</strong><span>33 views / 24 writes</span></div></div><LoadState loading={q.loading} error={q.error}><pre className="json-view">{JSON.stringify(q.data,null,2)}</pre></LoadState></>}

const CANDIDATE_TYPES=["OPEN_SOURCE_LIBRARY","DATASET","RESEARCH","DOCUMENTATION","DEVELOPER_TOOL","PUBLIC_ARCHIVE","COMMUNITY_INFRASTRUCTURE","PROTOCOL_COMPONENT","EDUCATIONAL_RESOURCE","CUSTOM"];
const CHECKPOINT_INTERVALS:[string,string][]=[["2592000","Every 30 days"],["7776000","Every 90 days"],["15552000","Every 180 days"],["31536000","Every 365 days"]];

export function Policies(){
 const obs=useContractRead<Page<ObservationPolicy>>("list_observation_policies",[0,50]);
 const fund=useContractRead<Page<FundingPolicy>>("list_funding_policies",[0,50]);
 const {wallet,submit}=useTx();const [obsError,setObsError]=useState<string>();const [fundError,setFundError]=useState<string>();
 const locked=!wallet.account||wallet.wrongNetwork;
 async function createObservation(e:FormEvent<HTMLFormElement>){e.preventDefault();setObsError(undefined);const form=e.currentTarget;const f=new FormData(form);const types=f.getAll("candidate_types").map(String);if(!types.length){setObsError("Select at least one candidate type this policy is allowed to observe.");return;}try{await submit("create_observation_policy",[String(f.get("name")),types,Number(f.get("minimum_evidence_categories")),Number(f.get("minimum_independent_sources")),String(f.get("latent_rules")),String(f.get("impact_rules")),String(f.get("lineage_rules")),String(f.get("gaming_rules")),String(f.get("substitute_rules")),Number(f.get("checkpoint_interval"))]);form.reset();await obs.refresh();}catch(x){setObsError(x instanceof Error?x.message:"Could not create the observation policy.");}}
 async function createFunding(e:FormEvent<HTMLFormElement>){e.preventDefault();setFundError(undefined);const form=e.currentTarget;const f=new FormData(form);const caps=["latent_cap_bps","watching_cap_bps","emerging_cap_bps","material_cap_bps","systemic_cap_bps"].map(k=>Number(f.get(k)));if(caps.some((v,i)=>i>0&&v<caps[i-1])){setFundError("Caps must never decrease: latent ≤ watching ≤ emerging ≤ material ≤ systemic.");return;}try{await submit("create_funding_policy",[String(f.get("name")),...caps,Number(f.get("minimum_public_value_bps")),Number(f.get("maximum_gaming_risk_bps")),Number(f.get("minimum_attribution_confidence_bps"))]);form.reset();await fund.refresh();}catch(x){setFundError(x instanceof Error?x.message:"Could not create the funding policy.");}}
 return <><PageHead eyebrow="REUSABLE PROTOCOL RULES" title="Observation and funding policies" lede="Policies are versioned, reusable, and bound to a candidate at registration. A candidate cannot be registered until one of each is active."/><TxBanner/>
 {!wallet.account&&<p className="hint">Connect a StudioNet wallet to create a policy. Reading existing policies needs no wallet.</p>}
 <div className="content-section"><div className="section-title"><h2>Observation policy</h2><span className="type">{obs.data?.total??0} CREATED</span></div><p className="muted">Defines which candidate types may be observed, how much independent evidence is required, and how often impact is checkpointed.</p>
  <form className="protocol-form compact" onSubmit={e=>void createObservation(e)}>
   <Field name="name" label="Policy name" required maxLength={120} placeholder="Baseline public infrastructure observation"/>
   <fieldset className="checkbox-grid"><legend>Candidate types this policy may observe</legend>{CANDIDATE_TYPES.map(t=><label key={t} className="check"><input type="checkbox" name="candidate_types" value={t} defaultChecked={t==="OPEN_SOURCE_LIBRARY"}/>{t.replace(/_/g," ")}</label>)}</fieldset>
   <div className="form-row"><Field name="minimum_evidence_categories" label="Minimum evidence categories (0-14)" type="number" min={0} max={14} defaultValue={3} required/><Field name="minimum_independent_sources" label="Minimum independent sources (1-100)" type="number" min={1} max={100} defaultValue={2} required/></div>
   <label>Checkpoint interval<select name="checkpoint_interval">{CHECKPOINT_INTERVALS.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>
   <Field name="latent_rules" label="Latent significance rules" textarea maxLength={2000} placeholder="What would make this look like future infrastructure rather than noise?"/>
   <Field name="impact_rules" label="Realized impact rules" textarea maxLength={2000} placeholder="What evidence would show the value actually materialized?"/>
   <Field name="lineage_rules" label="Lineage rules" textarea maxLength={2000} placeholder="How should foundational contribution be weighed against later derivative work?"/>
   <Field name="gaming_rules" label="Anti-gaming rules" textarea maxLength={2000} placeholder="Which adoption signals should be discounted as manufactured?"/>
   <Field name="substitute_rules" label="Substitute rules" textarea maxLength={2000} placeholder="How replaceable must an alternative be before it counts as a substitute?"/>
   {obsError&&<p className="form-error" role="alert">{obsError}</p>}
   <button className="button primary" disabled={locked}>Create observation policy</button>
  </form>
  <LoadState loading={obs.loading} error={obs.error} empty={!obs.data?.total} emptyTitle="No observation policies yet" emptyBody="Nothing can be observed until the rules for observing it exist on-chain." emptyAction={null}>
   <div className="checkpoint-table">{obs.data?.items.map(p=><div key={p.policy_id} className="policy-row"><b>#{p.policy_id} {p.name}</b><span>v{p.version} · {p.candidate_types.length} types · min {p.minimum_independent_sources} sources</span><StatusPill value={p.status}/></div>)}</div>
  </LoadState>
 </div>
 <div className="content-section"><div className="section-title"><h2>Funding policy</h2><span className="type">{fund.data?.total??0} CREATED</span></div><p className="muted">Caps cumulative recognition per importance tier in basis points, and sets the adjudication thresholds funding must clear. Caps must never decrease across tiers.</p>
  <form className="protocol-form compact" onSubmit={e=>void createFunding(e)}>
   <Field name="name" label="Policy name" required maxLength={120} placeholder="Progressive retroactive recognition"/>
   <div className="form-row"><Field name="latent_cap_bps" label="Latent cap (bps)" type="number" min={0} max={10000} defaultValue={500} required/><Field name="watching_cap_bps" label="Watching cap (bps)" type="number" min={0} max={10000} defaultValue={1500} required/></div>
   <div className="form-row"><Field name="emerging_cap_bps" label="Emerging cap (bps)" type="number" min={0} max={10000} defaultValue={3500} required/><Field name="material_cap_bps" label="Material cap (bps)" type="number" min={0} max={10000} defaultValue={6500} required/></div>
   <Field name="systemic_cap_bps" label="Systemic cap (bps)" type="number" min={0} max={10000} defaultValue={10000} required/>
   <div className="form-row"><Field name="minimum_public_value_bps" label="Minimum public value (bps)" type="number" min={0} max={10000} defaultValue={6000} required/><Field name="maximum_gaming_risk_bps" label="Maximum gaming risk (bps)" type="number" min={0} max={10000} defaultValue={3000} required/></div>
   <Field name="minimum_attribution_confidence_bps" label="Minimum attribution confidence (bps)" type="number" min={0} max={10000} defaultValue={6000} required/>
   <p className="hint">10000 bps = 100%. These are accounting caps, not token transfers.</p>
   {fundError&&<p className="form-error" role="alert">{fundError}</p>}
   <button className="button primary" disabled={locked}>Create funding policy</button>
  </form>
  <LoadState loading={fund.loading} error={fund.error} empty={!fund.data?.total} emptyTitle="No funding policies yet" emptyBody="Recognition cannot be calculated until the rules that cap it exist on-chain." emptyAction={null}>
   <div className="checkpoint-table">{fund.data?.items.map(p=><div key={p.funding_policy_id} className="policy-row"><b>#{p.funding_policy_id} {p.name}</b><span>v{p.version} · caps {p.latent_cap_bps}→{p.systemic_cap_bps} bps</span><StatusPill value={p.status}/></div>)}</div>
  </LoadState>
 </div></>;
}

export function LatentStage({set,locked,error,onRun}:{set:LatentSet;locked:boolean;error?:string;onRun(method:"freeze_latent_evidence"|"evaluate_latent_value"):void}){
 const cats=`${set.distinct_category_count}/${set.minimum_evidence_categories}`;
 const hosts=`${set.distinct_host_count}/${set.minimum_independent_sources}`;
 const catsMet=set.distinct_category_count>=set.minimum_evidence_categories;
 const hostsMet=set.distinct_host_count>=set.minimum_independent_sources;
 const canFreeze=!set.frozen&&set.candidate_status==="DISCOVERED"&&set.requirements_met;
 const canEvaluate=set.frozen&&set.candidate_status==="LATENT";
 return <><div className="latent-actions">
  <div className="gate">
   <span>evidence <b>{set.evidence_count}</b></span>
   <span className={catsMet?"met":undefined}>categories <b>{cats}</b></span>
   <span className={hostsMet?"met":undefined}>independent hosts <b>{hosts}</b></span>
   <span>{set.frozen?"set frozen":"set open"}</span>
  </div>
  {!set.frozen&&<button className="button primary" disabled={locked||!canFreeze} onClick={()=>onRun("freeze_latent_evidence")}>Freeze latent evidence</button>}
  {canEvaluate&&<button className="button primary" disabled={locked} onClick={()=>onRun("evaluate_latent_value")}>Evaluate latent value</button>}
 </div>
 {!set.frozen&&!set.requirements_met&&<p className="hint">The bound observation policy requires {set.minimum_evidence_categories} distinct evidence categories across {set.minimum_independent_sources} independent hosts before the set can be sealed.</p>}
 {canFreeze&&<p className="hint">Freezing is irreversible and happens once. No further latent evidence can be submitted afterwards.</p>}
 {error&&<p className="form-error" role="alert">{error}</p>}</>;
}
